  win='<div id="dx4-detail13" popover class="fenetre"><div class="barre"><span>Points clés raisonnés</span><button type="button" popovertarget="dx4-detail13" popovertargetaction="hide" aria-label="Fermer">✕</button></div><div class="corps"></div></div>'
